package com.nexamart.backend.api;import com.nexamart.backend.api.ApiModels.*;import com.nexamart.backend.domain.*;import com.nexamart.backend.service.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.time.*;
@RestController @RequestMapping("/api/v1/admin")public class AdminController{final AdminService s;final CatalogService catalog;public AdminController(AdminService s,CatalogService c){this.s=s;catalog=c;}@GetMapping("/dashboard")DashboardResponse dashboard(){return s.dashboard();}@GetMapping("/orders")PageResponse<OrderResponse> orders(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)String status,@RequestParam(required=false)Instant fromDate,@RequestParam(required=false)Instant toDate){return s.orderPage(page,pageSize,search,status==null?null:OrderStatus.valueOf(status),fromDate,toDate);}@GetMapping("/orders/{id}")OrderResponse order(@PathVariable Long id){return s.detail(id);}@PatchMapping("/orders/{id}/status")ResponseEntity<Void> status(@PathVariable Long id,@RequestBody OrderStatusRequest r){s.status(id,r);return ResponseEntity.noContent().build();}@PostMapping("/orders/{id}/cancel")ResponseEntity<Void> cancel(@PathVariable Long id,@RequestBody CancelRequest r){s.cancel(id,r);return ResponseEntity.noContent().build();}@PostMapping("/orders/{id}/assign")ResponseEntity<Void> assign(@PathVariable Long id,@RequestBody AssignRequest r){s.assign(id,r);return ResponseEntity.noContent().build();}
 @GetMapping("/customers")PageResponse<CustomerResponse> customers(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)AccountStatus status){return s.customers(page,pageSize,search,status);}@GetMapping("/customers/{id}")CustomerResponse customer(@PathVariable Long id){return s.customerDetail(id);}@PatchMapping("/customers/{id}/action")ResponseEntity<Void> customerAction(@PathVariable Long id,@RequestBody ActionRequest r){s.customerAction(id,r);return ResponseEntity.noContent().build();}
 @GetMapping("/delivery-partners")PageResponse<DeliveryPartnerResponse> partners(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)AccountStatus status){return s.partners(page,pageSize,search,status);}@GetMapping("/delivery-partners/{id}")DeliveryPartnerResponse partner(@PathVariable Long id){return s.partnerDetail(id);}@PatchMapping("/delivery-partners/{id}/action")ResponseEntity<Void> partnerAction(@PathVariable Long id,@RequestBody ActionRequest r){s.partnerAction(id,r);return ResponseEntity.noContent().build();}
 @GetMapping("/categories/{id}")CategoryResponse category(@PathVariable Long id){return catalog.categoryDetail(id);}@GetMapping("/categories")PageResponse<CategoryResponse> categories(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active){return catalog.categories(page,pageSize,search,active);}@PostMapping("/categories")CategoryResponse createCategory(@RequestBody java.util.Map<String,Object>b){return catalog.createCategory(b);}@PutMapping("/categories/{id}")CategoryResponse updateCategory(@PathVariable Long id,@RequestBody java.util.Map<String,Object>b){return catalog.updateCategory(id,b);}@PatchMapping("/categories/{id}/action")ResponseEntity<Void> categoryAction(@PathVariable Long id,@RequestBody ActionRequest r){catalog.categoryAction(id,r);return ResponseEntity.noContent().build();}
 @GetMapping("/products/{id}")ProductResponse product(@PathVariable Long id){return catalog.productDetail(id);}@PostMapping("/products/{id}/images")ProductImageResponse uploadProductImage(@PathVariable Long id,@RequestParam("file") MultipartFile file,@RequestParam(required=false) Integer sortOrder)throws java.io.IOException{ProductImage image=catalog.uploadProductImage(id,file.getBytes(),file.getContentType(),file.getOriginalFilename(),sortOrder);return new ProductImageResponse(image.getId(),"/api/v1/catalog/products/"+id+"/images/"+image.getId(),image.getSortOrder());}@DeleteMapping("/products/{id}/images/{imageId}")ResponseEntity<Void> deleteProductImage(@PathVariable Long id,@PathVariable Long imageId){catalog.deleteProductImage(id,imageId);return ResponseEntity.noContent().build();}@GetMapping("/products/categories")java.util.List<CatalogService.CategoryOption> productCategories(){return catalog.categoryOptions();}@GetMapping("/products")PageResponse<ProductResponse> products(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active,@RequestParam(required=false)Boolean outOfStock,@RequestParam(required=false)Long categoryId,@RequestParam(required=false)String sort){return catalog.products(page,pageSize,search,active,outOfStock,categoryId,sort);}@PostMapping("/products")ProductResponse createProduct(@RequestBody java.util.Map<String,Object>b){return catalog.createProduct(b);}@PutMapping("/products/{id}")ProductResponse updateProduct(@PathVariable Long id,@RequestBody java.util.Map<String,Object>b){return catalog.updateProduct(id,b);}@PatchMapping("/products/{id}/action")ResponseEntity<Void> productAction(@PathVariable Long id,@RequestBody ActionRequest r){catalog.productAction(id,r);return ResponseEntity.noContent().build();}

}
